func clampedSpeed(_ percent: Int) -> Int {
    if percent < 50 { percent = 50 }
    if percent > 200 { percent = 200 }
    return percent
}
print(clampedSpeed(30), clampedSpeed(125), clampedSpeed(250))

key:
func clampedSpeed(_ percent: Int) -> Int {
    var result = percent
    if result < 50 { result = 50 }
    if result > 200 { result = 200 }
    return result
}
print(clampedSpeed(30), clampedSpeed(125), clampedSpeed(250))

Параметр функции — константа: присвоить percent нельзя (cannot assign to value: 'percent' is a 'let' constant). Заводим локальную var и меняем её. Вывод: 50 125 200. Короче то же самое: min(max(percent, 50), 200).

